// profile.js
export const role='learner';
export function formatName(name){return name.trim()}
export default function createProfile(name){return {name:formatName(name),role}}
// app.js
import createProfile,{role,formatName} from './profile.js';
console.log(createProfile('Asha'),role,formatName(' Ravi '));

